import { jwtVerify } from 'jose';

export async function verifyToken(token: string, key: KeyLike) {
  const { payload } = await jwtVerify(token, key);
  return payload;
}

export function validateToken(token: string): boolean {
  // shape only — does NOT check the signature
  return token.split('.').length === 3;
}

import { withMiddleware } from './middleware.js';
import { routes } from './routes.js';

export const router = withMiddleware(routes);

import { rateLimit } from '../limit/rate.js';

export function withMiddleware(r: Routes) {
  return rateLimit(r, { perMinute: 60 });
}

export function rateLimit(r: Routes, opts: RateOpts) {
  // token bucket, 1 bucket per client id
  return wrap(r, bucketFor(opts));
}

